export const BODY: string = "\n<p>JPG کو PNG میں بدلنا سادہ کام ہے، مگر اسے درست کرنا قابل قدر ہے۔ درست تبدیلی فائل کو حقیقی PNG کے طور پر دوبارہ لکھتی ہے، صرف نام بدلی ہوئی JPG کے طور پر نہیں۔</p>\n<p>یہ طریقہ فی فائل سیکنڈوں میں مکمل ہوتا ہے، اور آپ ایک ساتھ بیس تصویریں بدل سکتے ہیں۔ سب کچھ آپ کے براؤزر میں چلتا ہے، بغیر کچھ انسٹال کیے۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، اور بتاتا ہے کہ نتیجہ استعمال کرنے سے پہلے کیا جانچیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: جانیں کہ آپ کیوں بدل رہے ہیں</h2>\n<p>خود سے پوچھیں کہ PNG کس لیے ہے۔ ایڈٹنگ، ڈیزائن کام اور متن والے اوورلے اچھی وجوہات ہیں۔ تصویر تیز یا چھوٹی کرنا نہیں ہیں، کیونکہ PNG دونوں نہیں کرتا۔</p>\n<p>جانچیں کہ PNG واقعی ضروری ہے یا نہیں۔ کچھ اوزار اس کا تقاضا کرتے ہیں، مگر کئی JPG یا WebP قبول کرتے ہیں، جو تصویروں کے لیے کہیں چھوٹے ہوتے ہیں۔</p>\n<p>اپنے پاس موجود بہترین JPG اصل تلاش کریں۔ PNG اسے بالکل محفوظ رکھے گی، خامیوں سمیت، اس لیے سب سے اونچی کوالٹی والی کاپی سے شروع کریں۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: JPG سے PNG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/jpg-ko-png-mein-convert-karein/\">JPG to PNG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ اور بدلیں بٹن دکھائی دے گا۔ کوالٹی سلائیڈر نہیں ہے، کیونکہ PNG بغیر نقصان والا ہے اور چننے کے لیے کوئی کوالٹی سطح نہیں ہوتی۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو ذاتی تصویروں اور اسکین شدہ دستاویزات کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی JPG فائلیں اپ لوڈ کریں</h2>\n<p>اپنی JPG فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ .jpg اور .jpeg دونوں ایکسٹینشن قبول ہوتی ہیں۔</p>\n<p>آپ ایک ساتھ بیس فائلیں اپ لوڈ کر سکتے ہیں۔ ہر ایک کارڈ کے طور پر دکھائی دیتی ہے، اپنے نام، ابعاد اور سائز کے ساتھ، تاکہ آپ یقین کر سکیں کہ درست فائلیں لوڈ ہوئیں۔</p>\n<p>ہر کارڈ پر ابعاد جانچیں۔ PNG JPG کی بالکل پکسل چوڑائی اور اونچائی رکھے گی، اس لیے غلط فائل یہاں آسانی سے نظر آ جاتی ہے۔</p>\n<h2 id=\"step-3-convert\">مرحلہ 3: فائلیں بدلیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ٹول ہر JPG ڈی کوڈ کرتا ہے، اسے کینوس پر بناتا ہے اور PNG کے طور پر انکوڈ کرتا ہے۔</p>\n<p>تبدیلی تیز ہوتی ہے، عام طور پر فی فائل ایک یا دو سیکنڈ۔ بڑی فائلیں تھوڑا زیادہ وقت لیتی ہیں، کیونکہ بغیر نقصان کے انکوڈ کرنے کے لیے زیادہ پکسل ہوتے ہیں۔</p>\n<p>ہر کارڈ پرانی JPG سائز کے ساتھ نیا PNG سائز دکھا کر اپ ڈیٹ ہوتا ہے۔ تصویروں کے لیے PNG بہت بڑی ہونے کی توقع رکھیں، اکثر JPG سائز سے پانچ سے دس گنا۔</p>\n<h2 id=\"step-4-compare\">مرحلہ 4: نتیجہ کا موازنہ کریں</h2>\n<p>کسی کارڈ پر Compare پر کلک کر کے ساتھ ساتھ دیکھنے والا منظر کھولیں۔ یہ JPG اور PNG ساتھ ساتھ دکھاتا ہے، تاکہ آپ صفر رنگ تبدیلی کی تصدیق کر سکیں۔</p>\n<p>کنارے اور متن قریب سے دیکھیں۔ PNG JPG جیسی ہی لگنی چاہیے، کیونکہ تبدیلی ہر پکسل بالکل محفوظ رکھتی ہے۔</p>\n<p>منظر میں ابعاد بھی جانچیں۔ چوڑائی اور اونچائی اصل JPG سے بالکل میل کھانی چاہییں، بغیر کراپ یا اسکیل کے۔</p>\n<h2 id=\"step-5-download\">مرحلہ 5: PNG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ایک PNG محفوظ کرنے کے لیے کسی کارڈ پر Download پر کلک کریں۔ فائل نام آپ کا اصل نام .png ایکسٹینشن کے ساتھ رکھتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی PNG ہو۔ یہ بیس فائلیں ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں تیز ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ PNG اپنے فوٹو ویور میں کھولیں اور یقین کریں کہ وہ درست لگتی ہے اور اس ایپ میں کھلتی ہے جسے اس کی ضرورت ہے۔</p>\n<ol>\n<li>JPG سے PNG ٹول کھولیں اور اپنی JPG فائلیں اپ لوڈ کریں۔</li>\n<li>Convert پر کلک کریں اور ہر کارڈ مکمل ہونے کا انتظار کریں۔</li>\n<li>کسی کارڈ کا موازنہ کر کے یقین کریں کہ رنگ بالکل میل کھاتے ہیں۔</li>\n<li>اکیلی PNG ڈاؤن لوڈ کریں یا پورا بیچ ZIP کے طور پر ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-a-batch\">بیس کا بیچ بدلنا</h2>\n<p>فائل پکر میں ایک ساتھ بیس JPG چنیں۔ وہ سب قطار میں لوڈ ہو جاتی ہیں، اور آپ انہیں ایک کلک سے ساتھ بدلتے ہیں۔</p>\n<p>بیچ چلتے ہوئے Change کالم دیکھیں۔ یہ فائل سائز بڑھنا صاف دکھاتا ہے، تاکہ آپ دیکھ سکیں کہ کون سی فائلیں سب سے زیادہ بڑھیں۔</p>\n<p>تصویریں سب سے زیادہ بڑھتی ہیں، کیونکہ ان کی بناوٹ PNG کے طور پر خراب کمپریس ہوتی ہے۔ سادہ اسکین اور گرافکس کہیں کم بڑھتے ہیں، کیونکہ ان کے فلیٹ حصے اچھی کمپریس ہوتے ہیں۔</p>\n<h2 id=\"checking-file-size\">بھیجنے سے پہلے فائل سائز جانچنا</h2>\n<p>ہمیشہ PNG سائز کسی بھی حد سے ملائیں۔ 5 MB تک اپ لوڈ دینے والا فارم ایسی PNG مسترد کر سکتا ہے جو 1 MB JPG سے شروع ہوئی تھی۔</p>\n<p>اگر PNG بہت بڑی ہو تو دوبارہ سوچیں کہ PNG ضروری ہے یا نہیں۔ WebP فائل اکثر بہتر سمجھوتا ہوتی ہے، چھوٹے سائز پر بغیر نقصان والی کوالٹی دیتی ہے۔</p>\n<p>ای میل منسلکات کے لیے بڑا PNG بیچ حد سے اوپر جا سکتا ہے۔ اس کی بجائے JPG بھیجیں، یا وصول کنندہ قبول کرے تو بدلنے کے بعد PNG کمپریس کریں۔</p>\n<h2 id=\"using-png-for-editing\">ایڈٹنگ کے لیے PNG استعمال کرنا</h2>\n<p>PNG اپنے پسندیدہ ایڈیٹر میں کھولیں۔ فوٹوشاپ، فگما، کینوا اور پاورپوائنٹ سب PNG خود قبول کرتے ہیں، اور بغیر نقصان والا فارمیٹ بار بار محفوظ کرنے سے بچ جاتا ہے۔</p>\n<p>PNG نسخے میں اپنا متن، تشریح یا اوورلے شامل کریں۔ ہر محفوظ کرنا تصویر کو پچھلی جیسی ہی تیز رکھتا ہے، بغیر جمع ہونے والے نقصان کے۔</p>\n<p>تیار نتیجہ اس فارمیٹ میں برآمد کریں جسے منزل چاہتی ہے۔ ویب صفحہ WebP یا JPG چاہتا ہے، جبکہ پرنٹ شاپ خود PNG چاہ سکتی ہے۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر PNG توقع سے کہیں بڑی نکلے تو تصویروں کے لیے یہ معمول ہے۔ PNG ہر پکسل بالکل محفوظ کرتا ہے، اور تفصیلی تصویر کو ایسا کرنے کے لیے کئی بائٹ چاہییں ہوتے ہیں۔</p>\n<p>اگر رنگ بدلے ہوئے لگیں تو ماخذ JPG نے CMYK پرنٹ رنگ استعمال کیے ہو سکتے ہیں۔ اس کی بجائے RGB برآمد بدلیں، یا نتیجہ استعمال سے پہلے احتیاط سے جانچیں۔</p>\n<p>اگر کوئی فائل بدلنے میں ناکام ہو تو جانچیں کہ یہ واقعی JPG ہے۔ .jpg نام والی فائل جو دراصل WebP یا PNG ہو، ڈی کوڈر کو الجھا دیتی ہے، اور اس کا نام درست کرنے سے مسئلہ حل ہو جاتا ہے۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور گیلری سے JPG چنیں۔ تبدیلی فون پر چلتی ہے، اور PNG آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی PNG موبائل پروسیسر پر انکوڈ ہونے میں وقت لیتی ہیں۔ ایک وقت میں پانچ فائلیں آرام دہ ہیں، بیس سست ہیں۔</p>\n<p>ڈاؤن لوڈ آپ کے فون کے Downloads فولڈر میں آتے ہیں۔ آئی فون پر Files ایپ جانچیں، اینڈرائیڈ پر اپنا فائل مینیجر جانچیں۔</p>\n<h2 id=\"old-family-photos\">پرانی خاندانی تصویریں بدلنا</h2>\n<p>پرانی خاندانی تصویریں اکثر JPG کے طور پر اسکین ہوتی ہیں، اور انہیں PNG میں بدلنے سے بحالی کے لیے بغیر نقصان والی کام کی کاپی بن جاتی ہے۔ PNG اسکین بالکل محفوظ رکھتی ہے، خامیوں سمیت، بغیر مزید نقصان جوڑے۔</p>\n<p>اپنے پاس موجود بہترین اسکین سے شروع کریں۔ 600 DPI پر اونچی ریزولوشن اسکین وہ تفصیل پکڑتا ہے جسے بحالی چاہیے ہوتی ہے، جبکہ کم ریزولوشن اسکین کسی فارمیٹ سے بہتر نہیں ہو سکتا۔</p>\n<p>بحالی کے شروع میں اسکین کو ایک بار PNG میں بدلیں۔ تمام ایڈٹ، دھول ہٹانے سے رنگ درست کرنے تک، PNG نسخے پر ہوتے ہیں، جو بار بار محفوظ کرنے سے بچ جاتا ہے۔</p>\n<h2 id=\"screenshots-for-manual\">دستی کے لیے اسکرین شاٹ بدلنا</h2>\n<p>صارف دستی اسکرین شاٹ سے بھرا ہوتا ہے، اور ان اسکرین شاٹ کو ایڈٹ کے کئی مرحلوں سے گزر کر پڑھنے کے قابل رہنا ہوتا ہے۔ شروع میں انہیں PNG میں بدلنا متن کی حفاظت کرتا ہے۔</p>\n<p>اسکرین شاٹ دستیاب سب سے اونچی ریزولوشن پر لیں۔ ریٹنا اسکرین شاٹ میں دگنے پکسل ہوتے ہیں، اور دستی پرنٹ ہونے کے بعد بھی متن تیز رہتا ہے۔</p>\n<p>تشریح شامل کرنے سے پہلے ہر اسکرین شاٹ PNG میں بدلیں۔ PNG پر شامل تیر، دائرے اور لیبل صاف رہتے ہیں، جبکہ JPG پر وہی تشریح ہر محفوظ کرنے پر نرم ہو جاتی ہے۔</p>\n<h2 id=\"images-for-designer\">ڈیزائنر کے لیے تصویریں بدلنا</h2>\n<p>ڈیزائنر PNG فائلیں پسند کرتے ہیں، کیونکہ وہ فوٹوشاپ، فگما اور الیسٹریٹر میں خود کھلتی ہیں۔ ڈیزائنر کو بھیجی گئی JPG اکثر ویسے بھی PNG میں بدل جاتی ہے، اس لیے PNG بھیجنے سے ایک مرحلہ بچ جاتا ہے۔</p>\n<p>بھیجنے سے پہلے تصویریں بدلیں، اور انہیں صاف نام دیں۔ hero-photo.png نام کی فائل ڈیزائنر کو بتاتی ہے کہ یہ کیا ہے، جبکہ IMG_4821.png کچھ نہیں بتاتی۔</p>\n<p>اپنے پاس موجود سب سے اونچی کوالٹی والے نسخے بھیجیں۔ کم کوالٹی JPG سے کام کرنے والا ڈیزائنر کتنا ہی ماہر ہو، تیز نتیجہ نہیں بنا سکتا۔</p>\n<h2 id=\"product-shots-editing\">ایڈٹنگ کے لیے مصنوعات کے شاٹ بدلنا</h2>\n<p>مصنوعات کی تصویروں کو دکان کے صفحے پر جانے سے پہلے ایڈٹ چاہیے ہوتا ہے۔ کراپ، پس منظر صفائی اور رنگ درست کرنا JPG کی بجائے PNG ماسٹر سے بہتر کام کرتے ہیں۔</p>\n<p>ایڈٹنگ سیشن کے شروع میں مصنوعات کی JPG کو ایک بار PNG میں بدلیں۔ تمام ایڈجسٹمنٹ PNG نسخوں پر ہوتی ہیں، جو بار بار محفوظ کرنے سے بغیر خراب ہوئے بچ جاتے ہیں۔</p>\n<p>پہلے ایک مصنوعات کی تصویر ایڈٹ کریں اور ٹیم سے شکل طے کریں۔ ایک منظور شدہ مثال پورے کیٹلاگ کا معیار طے کرتی ہے، اس لیے باقی اسی انداز پر چلتے ہیں۔</p>\n<h2 id=\"images-for-print\">پرنٹ کے لیے تصویریں بدلنا</h2>\n<p>پرنٹ کام کو دستیاب سب سے اونچی کوالٹی چاہیے ہوتی ہے، اور متن والی تصویروں کے لیے PNG محفوظ فارمیٹ ہے۔ پوسٹر، فلائر یا بروشر تیز حرفوں کے ساتھ PNG سے صاف پرنٹ ہوتا ہے۔</p>\n<p>بدلنے سے پہلے ریزولوشن جانچیں۔ 10 انچ پر پرنٹ شدہ 1000 پکسل تصویر صرف 100 DPI ہوتی ہے، جو فارمیٹ سے قطع نظر کاغذ پر نرم لگتی ہے۔</p>\n<p>تصویروں کو مکمل ریزولوشن پر PNG میں بدلیں، پھر انہیں پرنٹ شاپ کو بھیجیں۔ شاپ ضرورت ہو تو انہیں چھوٹا کر سکتی ہے، مگر وہ تفصیل نہیں جوڑ سکتی جو کبھی تھی ہی نہیں۔</p>\n<h2 id=\"images-for-school-assignment\">اسکول اسائنمنٹ کے لیے تصویریں بدلنا</h2>\n<p>اسکول اسائنمنٹ کو اکثر ویب سے تصویریں چاہییں ہوتی ہیں، اور وہ تصویریں عام طور پر JPG ہوتی ہیں۔ انہیں PNG میں بدلنے سے کراپ اور تشریح کے لیے بغیر نقصان والی کام کی کاپی ملتی ہے۔</p>\n<p>اسائنمنٹ میں شامل کرنے سے پہلے تصویروں کو PNG میں بدلیں۔ PNG بار بار ایڈٹ سے بچ جاتی ہیں، جبکہ ہر JPG محفوظ کرنا متن اور ڈایاگرام کو تھوڑا نقصان پہنچاتا ہے۔</p>\n<p>کئی تصویروں والی اسائنمنٹ کے لیے پورا سیٹ ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور PNG دستاویز میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<p>پورا طریقہ یہی ہے: اپ لوڈ کریں، بدلیں، موازنہ کریں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/jpg-ko-png-rehnumai/\">JPG to PNG: Complete Guide</a> پڑھیں، اور شفافیت سوال کے لیے <a href=\"/ur/blog/jpg-vs-png-transparency/\">JPG vs PNG: When Transparency Matters</a> دیکھیں۔ اگر آپ کو بڑی کی بجائے چھوٹی فائلیں چاہییں تو <a href=\"/ur/jpg-ko-webp-mein-convert-karein/\">JPG to WebP کنورٹر</a> استعمال کرنے والا ٹول ہے۔</p>\n";

